'use strict';

function pageCount(total, size) {
  return Math.floor(total / size);
}

function paginate(items, page, size) {
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be a positive integer');
  }
  const pages = pageCount(items.length, size);
  if (!Number.isInteger(page) || page < 1 || page > pages) {
    return { items: [], page, pages };
  }
  const start = (page - 1) * size;
  return { items: items.slice(start, start + size), page, pages };
}

module.exports = { pageCount, paginate };
--- src/summary.js ---
'use strict';

const { pageCount } = require('./paginate');

function summarize(total, size) {
  const pages = pageCount(total, size);
  const noun = pages === 1 ? 'page' : 'pages';
  return `${total} results across ${pages} ${noun}`;
}

module.exports = { summarize };
--- test/paginate.js ---
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { paginate } = require('../src/paginate');

const items = Array.from({ length: 6 }, (_, i) => i + 1);

test('returns the requested page', () => {
  assert.deepEqual(paginate(items, 2, 3), { items: [4, 5, 6], page: 2, pages: 2 });
});

test('returns no items past the last page', () => {
  assert.deepEqual(paginate(items, 3, 3).items, []);
});

test('rejects a non-positive page size', () => {
  assert.throws(() => paginate(items, 1, 0), RangeError);
});
--- test/summary.js ---
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { summarize } = require('../src/summary');

test('summarizes an exact multiple', () => {
  assert.equal(summarize(20, 10), '20 results across 2 pages');
});

